fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    // Determine how many participants to consider
    let limit = std::cmp::min(n as usize, participations.len());
    
    // Count eligible participants
    let mut eligible_count = 0;
    
    for i in 0..limit {
        let attendance = participations[i];
        // Check if participant can attend at least k more sessions
        if 5 - attendance >= k {
            eligible_count += 1;
        }
    }
    
    // Maximum number of teams is floor(eligible_count / 3)
    eligible_count / 3
}